const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const norwegianSea = ee.Geometry.Point([5.0, 67.0]).buffer(100000); // 100km radius
  const targetDate = '2019-06-05';
  const dateRange = ee.Filter.date('2019-06-04', '2019-06-06');

  // 2. Data Acquisition
  let collection = ee.ImageCollection('COPERNICUS/S2')
    .filterBounds(norwegianSea)
    .filter(dateRange)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

  const colSize = collection.size().getInfo();
  console.log(`Sentinel-2 images found: ${colSize}`);

  if (colSize === 0) {
    // Try wider date range
    collection = ee.ImageCollection('COPERNICUS/S2')
      .filterBounds(norwegianSea)
      .filter(ee.Filter.date('2019-06-01', '2019-06-10'))
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

    const colSize2 = collection.size().getInfo();
    console.log(`Extended search images: ${colSize2}`);

    if (colSize2 === 0) {
      console.log("No images found in Norwegian Sea for early June 2019.");
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // 3. Processing - Select best image and create chlorophyll indicator
  const image = collection.sort('CLOUDY_PIXEL_PERCENTAGE').first();

  // Light cloud mask
  const cloudMask = image.select('QA60').eq(0);
  const maskedImage = image.updateMask(cloudMask);

  // Check valid pixel count
  const pixelCount = maskedImage.select('B3').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: norwegianSea,
    scale: 3000,
    maxPixels: 1e9
  }).get('B3').getInfo();

  console.log(`Valid ocean pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("No valid pixels after cloud masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Phytoplankton bloom detection
  // Blooms show elevated green reflectance - use B3(Green)/B2(Blue) ratio
  const greenBand = maskedImage.select('B3');
  const blueBand = maskedImage.select('B2');
  const chlorophyllIndicator = greenBand.divide(blueBand);

  // Calculate statistics
  const stats = chlorophyllIndicator.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.max(),
      sharedInputs: true
    }).combine({
      reducer2: ee.Reducer.percentile([90]),
      sharedInputs: true
    }),
    geometry: norwegianSea,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const meanRatio = stats['B3_mean'];
  const maxRatio = stats['B3_max'];
  const p90Ratio = stats['B3_p90'];

  console.log(`Green/Blue ratio - Mean: ${meanRatio ? meanRatio.toFixed(3) : 'null'}, Max: ${maxRatio ? maxRatio.toFixed(3) : 'null'}, P90: ${p90Ratio ? p90Ratio.toFixed(3) : 'null'}`);

  // 5. Validation & Final Answer
  if (meanRatio === null || meanRatio === undefined || isNaN(meanRatio)) {
    console.log("Calculation failed - invalid results.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Phytoplankton blooms typically show Green/Blue > 1.2-1.3
  // Check if significant bloom signatures exist (high P90 or elevated mean)
  if (p90Ratio > 1.25 || meanRatio > 1.15) {
    console.log("Phytoplankton bloom signatures detected.");
    console.log("<answer>A</answer>");
  } else {
    console.log("No significant bloom signatures detected.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
